using System;
using System.Collections.Generic;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade piece cut from a surface. Travels on its own wire.</summary>
    public class Panel : IBettaValue
    {
        public Panel(Point3d a, Point3d b, Point3d c, Point3d d, int index)
        {
            Corners = new[] { a, b, c, d };
            Index = index;
        }

        /// <summary>The four corners, in order around the panel.</summary>
        public Point3d[] Corners { get; }

        /// <summary>Index in the grid.</summary>
        public int Index { get; }

        public Curve Outline
        {
            get
            {
                var c = Corners;
                return new PolylineCurve(new[] { c[0], c[1], c[2], c[3], c[0] });
            }
        }

        public Point3d Center
        {
            get
            {
                var c = Corners;
                return new Point3d(
                    (c[0].X + c[1].X + c[2].X + c[3].X) / 4,
                    (c[0].Y + c[1].Y + c[2].Y + c[3].Y) / 4,
                    (c[0].Z + c[1].Z + c[2].Z + c[3].Z) / 4);
            }
        }

        /// <summary>Area of the quad: half the cross product of its diagonals.</summary>
        public double Area =>
            0.5 * Vector3d.CrossProduct(Corners[2] - Corners[0], Corners[3] - Corners[1]).Length;

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation
        {
            get
            {
                var c = Corners;
                var normal = Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]);
                if (normal.Length < 1e-12)
                    return new Line(c[0], c[1]).DistanceTo(c[3], false);
                normal.Unitize();
                return Math.Abs(normal * (c[3] - c[0]));
            }
        }

        /// <summary>The four edge lengths, in order starting at the first edge.</summary>
        public double[] EdgeLengths
        {
            get
            {
                var c = Corners;
                return new[]
                {
                    c[0].DistanceTo(c[1]), c[1].DistanceTo(c[2]),
                    c[2].DistanceTo(c[3]), c[3].DistanceTo(c[0]),
                };
            }
        }

        public double[] DiagonalLengths =>
            new[] { Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3]) };

        /// <summary>Nesting width: mean of the first and third edge lengths.</summary>
        public double Width
        {
            get { var e = EdgeLengths; return (e[0] + e[2]) / 2; }
        }

        /// <summary>Nesting height: mean of the second and fourth edge lengths.</summary>
        public double Height
        {
            get { var e = EdgeLengths; return (e[1] + e[3]) / 2; }
        }
    }
}

