using System;
using System.Collections.Generic;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    [GrasshopperCollection("Facade", "Panels")]
    public interface IPanelCollection : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Divides a surface evenly into four-sided panels")]
        (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 6)] int vCount);

        [GrasshopperMethod("Panel Info", "Corners, outline, area, center and index of a panel")]
        (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(
            [GrasshopperParameter("Panel")] Panel panel);
    }

    public class PanelCollection : IPanelCollection
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentException("Surface is missing");
            if (uCount < 1 || vCount < 1)
                throw new ArgumentException("U Count and V Count must be at least 1");

            var du = surface.Domain(0);
            var dv = surface.Domain(1);
            var points = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    points[i, j] = surface.PointAt(
                        du.ParameterAt((double)i / uCount), dv.ParameterAt((double)j / vCount));

            var panels = new List<Panel>(uCount * vCount);
            var outlines = new List<Curve>(uCount * vCount);
            for (int i = 0; i < uCount; i++)
            {
                for (int j = 0; j < vCount; j++)
                {
                    var panel = new Panel(
                        points[i, j], points[i + 1, j], points[i + 1, j + 1], points[i, j + 1],
                        i * vCount + j);
                    panels.Add(panel);
                    outlines.Add(panel.Outline);
                }
            }
            return (panels, outlines);
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentException("Panel is missing");
            return (new List<Point3d>(panel.Corners), panel.Outline, panel.Area, panel.Center, panel.Index);
        }
    }
}

