                        (h + 2 * spacing <= sheetWidth && w + 2 * spacing <= sheetHeight);
                    if (!fitsEmptySheet) { unplaced++; continue; }

                    double pw = w, ph = h;
                    bool placed = false;
                    if (sheet >= 0)
                    {
                        // current shelf, as is, then turned
                        if (x + w <= maxX && h <= shelfH) { placed = true; }
                        else if (x + h <= maxX && w <= shelfH) { pw = h; ph = w; placed = true; }
                    }
                    if (!placed)
                    {
                        // new shelf above on the current sheet
                        double y = sheet >= 0 ? shelfY + shelfH + spacing : 0;
                        if (sheet >= 0 && spacing + w <= maxX && y + h <= maxY) { placed = true; }
                        else if (sheet >= 0 && spacing + h <= maxX && y + w <= maxY) { pw = h; ph = w; placed = true; }
                        if (placed)
                        {
                            shelfY = y; shelfH = ph; x = spacing;
                        }
                        else
                        {
                            // new sheet
                            sheet++;
                            if (spacing + w <= maxX && spacing + h <= maxY) { }
                            else { pw = h; ph = w; }
                            shelfY = spacing; shelfH = ph; x = spacing;
                        }
                    }

                    double ox = sheet * (sheetWidth + 100) + x;
                    var rect = new PolylineCurve(new[]
                    {
                        new Point3d(ox, shelfY, 0), new Point3d(ox + pw, shelfY, 0),
                        new Point3d(ox + pw, shelfY + ph, 0), new Point3d(ox, shelfY + ph, 0),
                        new Point3d(ox, shelfY, 0),
                    });
                    outlines.Add(rect);
                    sheets.Add(sheet);
                    placedArea += pw * ph;
                    x += pw + spacing;
                }
                progress?.Report(1.0);

                if (unplaced > 0) report.Warning($"{unplaced} panels fit on no sheet");
                int sheetCount = sheet + 1;
                double utilization = sheetCount == 0 ? 0 : placedArea / (sheetCount * sheetWidth * sheetHeight);
                return (outlines, sheets, sheetCount, utilization);
            }, cancellationToken);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Path is empty");

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels ?? new List<Panel>())
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.Width.ToString("R", inv)).Append(',')
                  .Append(p.Height.ToString("R", inv)).Append(',')
                  .Append(p.Area.ToString("R", inv)).Append(',')
                  .Append(p.Deviation.ToString("R", inv)).Append('\n');
            string csv = sb.ToString();

            if (!write) return (csv, false);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
